const $=id=>document.getElementById(id);let review=null;let reviewedText='';
function update(){const n=TraceEngine.words($('content').value).length;$('wordcount').textContent=n.toLocaleString();$('charcount').textContent=$('content').value.length.toLocaleString();$('analyze').disabled=n===0;if(review&&reviewedText!==$('content').value){review=null;$('results').hidden=true;$('empty').hidden=false;$('evidence').hidden=true;$('resultbadge').textContent='TEXT CHANGED';}$('message').textContent='';}
$('content').addEventListener('input',update);
function openMethod(){$('method').showModal();}['navMethod','learn','methodFooter'].forEach(id=>$(id).onclick=openMethod);$('closeMethod').onclick=()=>$('method').close();$('method').addEventListener('click',e=>{if(e.target===$('method')){const r=$('method').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('method').close();}});$('navReview').onclick=()=>$('content').focus();
$('clear').onclick=()=>{$('content').value='';review=null;$('results').hidden=true;$('empty').hidden=false;$('evidence').hidden=true;$('resultbadge').textContent='AWAITING TEXT';$('file').value='';update();$('content').focus();};
$('upload').onclick=()=>$('file').click();$('file').onchange=async()=>{const f=$('file').files[0];if(!f)return;if(!/\.(txt|md)$/i.test(f.name)){$('message').textContent='Choose a .txt or .md file.';return;}if(f.size>500000){$('message').textContent='Choose a text file smaller than 500 KB.';return;}try{const t=await f.text();if(t.length>100000){$('message').textContent='This file exceeds the 100,000-character limit. Please shorten it.';return;}$('content').value=t;update();}catch{$('message').textContent='The file could not be read. Please paste its text instead.';}};
$('sample').onclick=()=>{$('content').value=`In today's fast-paced world, organizations are looking for better ways to communicate. It is important to note that effective communication plays a pivotal role in building trust across a growing team. Furthermore, shared processes can help people understand their responsibilities and move forward with confidence.

The team can build trust by making its goals visible to everyone involved. The team can build momentum by scheduling regular conversations about progress and challenges. The team can build clarity by documenting important decisions and sharing them with the people affected. These practices provide a consistent foundation, although each organization will need to adapt its approach to its circumstances.

Moreover, leaders should consider how information reaches people who work different hours or in different locations. A written summary may be more useful than an extra meeting. Asking colleagues which information they are missing can reveal practical opportunities for improvement. In conclusion, communication deserves ongoing attention, and small changes can make daily work easier for the people doing it.`;update();$('message').textContent='Illustrative sample written for this demo. The rules measure its style, not its provenance.';};
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function highlight(text,phrases){const box=el('div','passage');const escaped=phrases.map(p=>p.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));if(!escaped.length){box.textContent=text;return box;}const reg=new RegExp('('+escaped.join('|')+')','gi');let pos=0;for(const match of text.matchAll(reg)){box.append(document.createTextNode(text.slice(pos,match.index)));box.append(el('mark','',match[0]));pos=match.index+match[0].length;}box.append(document.createTextNode(text.slice(pos)));return box;}
$('analyze').onclick=()=>{const text=$('content').value;if(!TraceEngine.words(text).length)return;review=TraceEngine.analyze(text);reviewedText=text;$('empty').hidden=true;$('results').hidden=false;$('evidence').hidden=false;$('resultbadge').textContent=review.enough?'REVIEW COMPLETE':'LIMITED SAMPLE';$('verdict').textContent=review.verdict;$('signals').textContent=review.signalCount+' / 4';$('sentences').textContent=review.sentenceCount;$('variation').textContent=review.variation.toFixed(2);$('summarytext').textContent=review.enough?(review.signalCount?'Some stylistic patterns deserve a closer look. Review each observation in context.':'Few listed patterns were observed. This does not establish human authorship.'):'Limited sample: aim for 150 words and 5 sentences. Sentence uniformity is not assessed until both minimums are met.';$('signalList').replaceChildren();review.signals.forEach(s=>{const item=el('div','signal');const head=el('div','signalhead');head.append(el('h3','',s.name),el('span','pill'+(s.flag?' flag':''),s.flag?'Observed':'Not observed'));item.append(head,el('p','',s.observation),el('p','',s.reason),el('small','',s.rule));$('signalList').append(item);});$('passages').replaceChildren();if(review.passages.length){review.passages.forEach(p=>$('passages').append(highlight(p,review.phrases)));}else{$('passages').append(el('div','passage','No passages matched the phrase or repetition rules. Review the overall metrics alongside the full text.'));}$('message').textContent='Review complete. No text has left this browser.';};
$('export').onclick=()=>{if(!review)return;const report={...review,reviewedAt:new Date().toISOString(),fullTextIncluded:false,excerptsIncluded:true};const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=el('a');a.href=url;a.download='trace-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
